mapper.update:
update pokemon set
pokemon_name=#{pokemonName}, pokemon_type=#{pokemonType}, pokemon_like=#{pokemonLike}
where pokemon_no=#{pokemonNo}

mapper.select:
select * from (
	select rownum rn, TMP.* from (
		select * from pokemon order by pokemon_no desc
	)TMP
) where rn between #{begin} and #{end}
